        sandbox.apply_force(paddles[2], -520, 0, step_count)

def build_agent(sandbox):
    # Main body: width 2.0m, height 1.0m, density 50 kg/m³
    main_body = sandbox.add_beam(x=5.0, y=1.88, width=2.0, height=1.0, density=50.0)

    # Add four paddles on the right side, spread out to avoid overlap
    paddle_positions = [(6.0, 1.88), (6.0, 1.98), (6.2, 1.88), (6.2, 1.98)]
    paddles = []
    for x, y in paddle_positions:
        paddle = sandbox.add_beam(x=x, y=y, width=0.5, height=0.5, density=100.0)
        paddles.append(paddle)

    # Connect each paddle to main body with rigid joints
    for paddle in paddles:
        sandbox.add_joint(main_body, paddle, anchor_point=(paddle.position.x, paddle.position.y), type='rigid')

    return main_body

def agent_action(sandbox, agent_body, step_count):
    # Identify paddles (exclude the main body)
    paddles = [body for body in sandbox.bodies if body != agent_body]

    # Apply force to all paddles every 3 steps to respect cooldown
    if step_count % 3 == 0:
        for paddle in paddles:
            sandbox.apply_force(paddle, 520, 0, step_count)
